correct_pin = "2580"
max_attempts = 3
attempts = 0
unlocked = False

while attempts < max_attempts and not unlocked:
    pin = input("Enter PIN: ")
    attempts += 1
    if pin == correct_pin:
        unlocked = True
    else:
        print(f"Wrong PIN, {max_attempts - attempts} left")

if unlocked:
    print(f"Unlocked after {attempts} attempt(s)")
else:
    print("Card blocked. Contact your bank.")
